WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_analysis_graphic_material'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '图形资料', 'kp-xingce-data-analysis-graphic-material', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "图形资料综述"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "通过直观图形展示数据的材料，看四要素防陷阱是核心。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "包含柱状图、折线图、饼图等。找数快，但极容易在单位和图例上翻车。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心法则"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "读图先看“四要素”——标题、横纵轴、图例、脚注。缺一不可。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[拿到图形材料] --> B[看标题: 确定时间与总体分类]\nB --> C[看坐标轴: 横轴看时间跨度, 纵轴看 单位(万还是亿?)]\nC --> D[看图例: 确认黑色柱子代表什么, 白色柱子代表什么]\nD --> E[看脚注: 下方是否有带 * 的特殊说明]\nE --> F[开始看题干做题]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【场景】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 图形是一张 2018-2023 年产值的柱状图。横轴是年份，纵轴单位是“百万元”。图例黑色是“东部”，白色是“西部”。"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "扫标题：了解大盘。扫坐标轴：发现单位是“百万”，这就埋下了一个大坑，计算时极容易差两个零。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "扫图例：明确黑白柱归属。如果不看图例，做题时容易把西部的当成东部的算。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "扫脚注：发现“*2020年数据包含暂估数据”。如果题目问2020年的定性分析，就要小心。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "起点陷阱（截断坐标轴）：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "为了让变化显得剧烈，图表的纵轴起点可能不是 0，而是 1000。此时图形 A 看起来是图形 B 的两倍高，但实际数值可能只是 1100 和 1050 的区别。切忌纯凭肉眼判断倍数关系！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "无论多简单的图，必须强迫自己看一眼纵坐标最上方的单位括号！"}]}]}$$ AS jsonb), NULL, '图形资料的核心读题与防坑技巧。', category_node.id, CAST('["资料分析", "图形资料"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_analysis_graphic_material", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
